import { createServer } from 'node:http';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_FILE = join(__dirname, 'data', 'books.json');
const PORT = process.env.PORT || 3000;

async function loadBooks() {
  try {
    const raw = await readFile(DATA_FILE, 'utf8');
    return JSON.parse(raw);
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function saveBooks(books) {
  await mkdir(dirname(DATA_FILE), { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2));
}

function escapeHtml(str) {
  return String(str ?? '').replace(/[&<>"']/g, (c) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  }[c]));
}

async function readBody(req) {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  const raw = Buffer.concat(chunks).toString('utf8');
  return Object.fromEntries(new URLSearchParams(raw));
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<link rel="stylesheet" href="/style.css">
</head>
<body>
<header><a class="home-link" href="/">📚 My Books</a></header>
<main>
${body}
</main>
</body>
</html>`;
}

function bookRow(book) {
  return `<li class="book-row">
  <a href="/book/${book.id}">${escapeHtml(book.title)}</a>
  <span class="author">by ${escapeHtml(book.author)}</span>
  ${book.status === 'reading' ? `
  <form method="post" action="/books/${book.id}/finish" class="inline-form">
    <button type="submit">Mark finished</button>
  </form>` : ''}
</li>`;
}

function renderHome(books) {
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books.filter((b) => b.status === 'finished');

  const body = `
<section>
  <h2>Currently Reading</h2>
  ${reading.length ? `<ul class="book-list">${reading.map(bookRow).join('')}</ul>` : '<p class="empty">Nothing yet.</p>'}
</section>

<section>
  <h2>Finished</h2>
  ${finished.length ? `<ul class="book-list">${finished.map(bookRow).join('')}</ul>` : '<p class="empty">Nothing yet.</p>'}
</section>

<section>
  <h2>Add a book</h2>
  <form method="post" action="/books" class="add-form">
    <label>Title<br><input type="text" name="title" required></label>
    <label>Author<br><input type="text" name="author" required></label>
    <label>Notes<br><textarea name="notes" rows="3"></textarea></label>
    <button type="submit">Add book</button>
  </form>
</section>`;

  return layout('My Books', body);
}

function renderBook(book, shareUrl) {
  const body = `
<p><a href="/">&larr; Back to all books</a></p>
<article class="book-detail">
  <h1>${escapeHtml(book.title)}</h1>
  <p class="author">by ${escapeHtml(book.author)}</p>
  <p class="status">Status: <strong>${book.status === 'reading' ? 'Currently reading' : 'Finished'}</strong></p>

  ${book.status === 'reading' ? `
  <form method="post" action="/books/${book.id}/finish">
    <button type="submit">Mark finished</button>
  </form>` : ''}

  <h2>Notes</h2>
  <form method="post" action="/books/${book.id}/notes" class="notes-form">
    <textarea name="notes" rows="8">${escapeHtml(book.notes)}</textarea>
    <button type="submit">Save notes</button>
  </form>

  <h2>Share this book</h2>
  <p>Send this link: <input type="text" readonly value="${escapeHtml(shareUrl)}" onclick="this.select()" class="share-link"></p>
</article>`;

  return layout(book.title, body);
}

function notFound(res) {
  res.writeHead(404, { 'Content-Type': 'text/html' });
  res.end(layout('Not found', '<p>Book not found.</p><p><a href="/">Back home</a></p>'));
}

const CSS = `
* { box-sizing: border-box; }
body { font-family: system-ui, sans-serif; max-width: 640px; margin: 0 auto; padding: 1rem; color: #222; line-height: 1.5; }
header { margin-bottom: 1.5rem; }
.home-link { font-size: 1.25rem; font-weight: bold; text-decoration: none; color: #222; }
h2 { font-size: 1.1rem; margin-top: 2rem; }
.book-list { list-style: none; padding: 0; }
.book-row { display: flex; align-items: center; gap: 0.5rem; padding: 0.5rem 0; border-bottom: 1px solid #eee; }
.book-row a { font-weight: 600; text-decoration: none; color: #1a5fb4; }
.book-row a:hover { text-decoration: underline; }
.author { color: #666; font-size: 0.9rem; }
.inline-form { margin-left: auto; }
.empty { color: #888; font-style: italic; }
form.add-form, form.notes-form { display: flex; flex-direction: column; gap: 0.75rem; max-width: 480px; }
input, textarea { font: inherit; padding: 0.4rem; border: 1px solid #ccc; border-radius: 4px; width: 100%; }
button { font: inherit; padding: 0.5rem 1rem; border: none; border-radius: 4px; background: #1a5fb4; color: #fff; cursor: pointer; width: fit-content; }
button:hover { background: #144a8f; }
.share-link { width: 100%; max-width: 480px; }
`;

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const { pathname } = url;

  try {
    if (req.method === 'GET' && pathname === '/style.css') {
      res.writeHead(200, { 'Content-Type': 'text/css' });
      return res.end(CSS);
    }

    if (req.method === 'GET' && pathname === '/') {
      const books = await loadBooks();
      res.writeHead(200, { 'Content-Type': 'text/html' });
      return res.end(renderHome(books));
    }

    if (req.method === 'POST' && pathname === '/books') {
      const { title, author, notes } = await readBody(req);
      if (!title?.trim() || !author?.trim()) {
        res.writeHead(400, { 'Content-Type': 'text/html' });
        return res.end(layout('Error', '<p>Title and author are required.</p><p><a href="/">Back</a></p>'));
      }
      const books = await loadBooks();
      books.push({
        id: randomUUID(),
        title: title.trim(),
        author: author.trim(),
        notes: notes?.trim() || '',
        status: 'reading',
        addedAt: new Date().toISOString(),
      });
      await saveBooks(books);
      res.writeHead(303, { Location: '/' });
      return res.end();
    }

    const bookMatch = pathname.match(/^\/book\/([^/]+)$/);
    if (req.method === 'GET' && bookMatch) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === bookMatch[1]);
      if (!book) return notFound(res);
      const shareUrl = `${url.protocol}//${req.headers.host}/book/${book.id}`;
      res.writeHead(200, { 'Content-Type': 'text/html' });
      return res.end(renderBook(book, shareUrl));
    }

    const finishMatch = pathname.match(/^\/books\/([^/]+)\/finish$/);
    if (req.method === 'POST' && finishMatch) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === finishMatch[1]);
